class RunningStats:
    def __init__(self):
        self.n = 0
        self.mu = 0.0
        self.m2 = 0.0

    def update(self, x):
        self.n += 1
        delta = x - self.mu
        self.mu += delta / self.n
        self.m2 += delta * (x - self.mu)

    @property
    def mean(self):
        return self.mu

    @property
    def variance(self):
        return self.m2 / self.n if self.n else 0.0
